/**
 * 키 고르기(순수 함수): 눌린 키와 지금 상황으로 할 일을 정한다. 실제 이벤트 처리는 app.ts가 한다.
 *
 * - 뷰어 키(F 전체 보기, 1~7 표준 뷰, Esc 측정 지우기)의 규칙은 뷰어 코어가 가진다(Viewer3d.handleKey).
 *   캔버스에 초점이 있으면 뷰어가 직접 받고, 초점이 다른 곳(단추·패널 등)이면 앱이 창 키를 handleKey로 넘긴다
 *   (171차: 설정 「3D 보기 밖에서도 한 글자 단축키」를 끄면 글자·숫자 키 F·1~7은 넘기지 않는다 — 3D 보기에 초점이 있을 때만, WCAG 2.1.4).
 * - 입력 칸(글·선택 상자)에서는 아무것도 가로채지 않는다.
 * - 앱 키: F7 = 격자, Space = 재생/멈춤(버튼·체크 상자처럼 Space를 스스로 쓰는 칸에 초점이 있으면 그 칸에 둔다 — isPressTarget), Ctrl/⌘+O = 열기,
 *   Esc = (측정 중이면 측정 먼저) 고른 것 지우기.
 * - 측정 첫 점을 찍은 뒤(둘째 점 방향을 잡는 동안) 화살표는 방향 잠금(SketchUp 추론 잠금): → X · ← Y · ↑ Z축, ↓ 지금 방향.
 *   코드 목록·메뉴·탭처럼 화살표를 스스로 쓰는 곳에 초점이 있으면 그쪽 것이다. Shift 잠금은 코어가 한다.
 * - 150차: 패널 탭 버튼의 ←→·Home·End(수정 키 없음)는 탭 줄 몫이다(tabMove — 위 앱 화살표의 한 이동 걷기보다 먼저).
 * - 56차(코어 0.46.0 키보드 붙잡기 — keysnap.ts): 캔버스의 가상 커서가 켜진 동안 화살표·Esc는 코어 것이다(커서 옮기기·끄기 — 위 앱 화살표보다 먼저).
 *   커서는 Enter로만 켠다(커서가 꺼져 있을 때 캔버스 화살표는 keysnap.ts가 기본 동작을 막아 코어가 커서를 켜지 않는다 — 문서 종류마다 화살표 뜻이 갈리지 않게).
 *   203차: 커서가 켜진 동안의 측정 축 잠금은 캔버스의 X·Y·Z(측정 조각 measure-lock.ts axisKey — 여기 키 고르기는 캔버스 글자 키를 코어에 두므로 닿지 않는다). 204차: 지금 방향은 L(같은 자리).
 * - 205차: ? = 키보드 단축키 창(문서가 없어도 — 시작 화면, 171차 설정을 끄면 다른 한 글자 키처럼 3D 보기에서만). 그 창(shortcuts.ts SHORTCUTS)은 여기서 고르는 키와 같게 둔다
 *   (tests/app/shortcuts.test.ts — 키를 더하면 창에도). 창(aria-modal) 안의 키는 app.ts onKey가 여기 오기 전에 돌아선다.
 */
import type { ViewName } from 'opencad-viewer3d';
// 숫자 키 → 표준 뷰 표는 코어의 작은 모듈에서(0.10.0 — 코어 입구는 문서를 열 때 나눠 받으므로 첫 화면 메뉴 글은 camera 모듈의 표로)
import { VIEW_KEYS } from 'opencad-viewer3d/camera';

export type KeyAction =
  | { type: 'open' }
  | { type: 'grid' }
  | { type: 'play' }
  /** 캔버스 밖의 키를 뷰어 규칙(handleKey)으로 넘긴다 — 뷰어가 받지 않는 키면 아무 일도 없다 */
  | { type: 'viewer' }
  /**
   * Esc의 앱 쪽 처리. canvas: 캔버스가 받은 Esc(뷰어가 스스로 측정을 지우므로 앱은 측정 중이 아닐 때 고른 것만 지운다).
   * 캔버스 밖이면 측정 중일 때 handleKey로 측정을 먼저 지우고(점이 없으면 측정을 끈다), 아니면 고른 것을 지운다.
   */
  | { type: 'escape'; canvas: boolean }
  /** ← → 한 이동씩(Shift면 10) */
  | { type: 'step'; delta: number }
  /** ← → 판재 깎기에서 한 가공씩(가공 하나씩 따라가기) */
  | { type: 'opStep'; delta: number }
  /** ↑ ↓ 고른 줄을 앞·뒤로(캔버스·코드 목록에 초점이 있을 때) */
  | { type: 'line'; delta: number }
  /** Ctrl/⌘+F 코드에서 찾기, Ctrl/⌘+G 다음 찾기 */
  | { type: 'find'; next: boolean }
  /** 측정 방향 잠금(화살표): 축, 또는 null = 지금 방향(나란함·수직·축) */
  | { type: 'lock'; axis: 'x' | 'y' | 'z' | null }
  /** 205차: ? 키보드 단축키 창 */
  | { type: 'shortcuts' };

export interface KeyContext {
  key: string;
  ctrl: boolean;
  meta: boolean;
  alt: boolean;
  /** 글을 넣는 곳(input·textarea·select·contenteditable)에 초점 */
  editable: boolean;
  /** 초점이 Space를 스스로 쓰는 누름 칸(버튼·링크·체크 상자 등 — isPressTarget) */
  onButton: boolean;
  /** 초점이 뷰어 캔버스 */
  onCanvas: boolean;
  /** 열린 문서가 있음 */
  hasDoc: boolean;
  /** 재생할 수 있음(G-code·Heidenhain이고 이동이 있음) */
  canPlay: boolean;
  /** Shift를 눌렀는지 */
  shift?: boolean;
  /** 초점이 코드 목록 안 */
  inCode?: boolean;
  /** 열린 문서에 코드가 있음(찾기) */
  hasCode?: boolean;
  /** 측정 첫 점을 찍었고 결과가 없음(둘째 점 방향을 잡는 중 — 화살표는 방향 잠금) */
  measureDirecting?: boolean;
  /** 화살표를 스스로 쓰는 곳(코드 목록·메뉴·탭·목록)에 초점 */
  arrowOwner?: boolean;
  /** 판재 파일을 깎아 보는 중(가공 하나씩 따라가기를 할 수 있음 — ← → 한 가공씩) */
  canStepOps?: boolean;
  /** 3D 보기의 가상 커서가 켜져 있음(코어 keyboardCursor — 캔버스의 화살표·Esc는 코어가 받는다) */
  keyCursor?: boolean;
  /** 171차: 설정 「3D 보기 밖에서도 한 글자 단축키」를 껐음(캔버스 밖의 글자 키를 뷰어로 넘기지 않는다 — 기본은 켬) */
  charKeysOff?: boolean;
}

/** 화살표 → 잠글 축(↓는 지금 방향 = null) */
const LOCK_KEYS: Record<string, 'x' | 'y' | 'z' | null> = { ArrowRight: 'x', ArrowLeft: 'y', ArrowUp: 'z', ArrowDown: null };

export function keyAction(c: KeyContext): KeyAction | null {
  const mod = c.ctrl || c.meta;
  if (c.editable) return null;
  if (mod && !c.alt && (c.key === 'o' || c.key === 'O')) return { type: 'open' };
  // 코드 찾기: 가상 목록이라 브라우저 찾기(Ctrl+F)로는 보이지 않는 줄을 못 찾는다 — 앱의 찾기 칸으로
  if (mod && !c.alt && c.hasDoc && c.hasCode && (c.key === 'f' || c.key === 'F')) return { type: 'find', next: false };
  if (mod && !c.alt && c.hasDoc && c.hasCode && (c.key === 'g' || c.key === 'G')) return { type: 'find', next: true };
  if (mod || c.alt) return null;
  if (c.key === '?') return c.charKeysOff && !c.onCanvas ? null : { type: 'shortcuts' };
  if (!c.hasDoc) return null;
  if (c.key === 'F7') return { type: 'grid' };
  if (c.key === ' ' || c.key === 'Spacebar') return c.canPlay && !c.onButton ? { type: 'play' } : null;
  if (c.keyCursor && c.onCanvas && (c.key.startsWith('Arrow') || c.key === 'Escape')) return null;
  if (c.key === 'Escape') return { type: 'escape', canvas: c.onCanvas };
  if (c.measureDirecting && !c.arrowOwner && !c.inCode && c.key in LOCK_KEYS) return { type: 'lock', axis: LOCK_KEYS[c.key] ?? null };
  if ((c.key === 'ArrowRight' || c.key === 'ArrowLeft') && c.canPlay) return { type: 'step', delta: (c.key === 'ArrowRight' ? 1 : -1) * (c.shift ? 10 : 1) };
  if ((c.key === 'ArrowRight' || c.key === 'ArrowLeft') && c.canStepOps && !c.arrowOwner && !c.inCode) return { type: 'opStep', delta: c.key === 'ArrowRight' ? 1 : -1 };
  if ((c.key === 'ArrowDown' || c.key === 'ArrowUp') && (c.onCanvas || c.inCode)) return { type: 'line', delta: c.key === 'ArrowDown' ? 1 : -1 };
  // 171차(WCAG 2.1.4 문자 키 단축키): 설정 「3D 보기 밖에서도 한 글자 단축키」를 끄면 글자·숫자·기호 키 하나(F 전체 보기·1~7 표준 뷰 — Space는 위에서 따로)는
  // 3D 보기(캔버스)에 초점이 있을 때만 — 코어가 캔버스에서 직접 받는다. 켜 두면(기본) 캔버스 밖(초점 없는 body·버튼·패널·코드 목록)에서도 넘긴다(170차까지 그대로)
  return c.onCanvas || (c.charKeysOff && c.key.length === 1) ? null : { type: 'viewer' };
}

/** 171차: 설정 「3D 보기 밖에서도 한 글자 단축키(F·1~7·?)」(205차 ? 더함)의 localStorage 열쇠(값 'off'면 끔 — 없거나 못 읽으면 켬) */
export const CHAR_KEYS_KEY = 'opencad-nc.charKeys';

/** 171차: 기억한 「3D 보기 밖에서도 한 글자 단축키」 켬 여부(기본 켬 — 저장소가 없거나 예외를 던지면 켬) */
export function readCharKeysPref(s: Pick<Storage, 'getItem'> | null): boolean {
  try {
    return s?.getItem(CHAR_KEYS_KEY) !== 'off';
  } catch {
    return true;
  }
}

/** 171차: 켬 여부를 기억한다(저장소가 없거나 실패하면 조용히 넘어간다 — 이번 창에서만). 기억했으면 true */
export function writeCharKeysPref(s: Pick<Storage, 'setItem'> | null, on: boolean): boolean {
  if (!s) return false;
  try {
    s.setItem(CHAR_KEYS_KEY, on ? 'on' : 'off');
    return true;
  } catch {
    return false;
  }
}

/** 표준 뷰 → 숫자 키(메뉴 글용, VIEW_KEYS를 뒤집은 것). 키가 없는 뷰는 undefined */
export function viewKeyOf(view: ViewName): string | undefined {
  for (const [k, v] of Object.entries(VIEW_KEYS)) if (v === view) return k;
  return undefined;
}

/** 초점 요소가 글 입력 칸인지(범위 막대·체크 상자·단추형 input은 아니다) */
export function isEditableTarget(t: { tagName?: string; type?: string; isContentEditable?: boolean } | null): boolean {
  if (!t || !t.tagName) return false;
  const tag = t.tagName.toUpperCase();
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') {
    const type = (t.type ?? 'text').toLowerCase();
    return !['range', 'checkbox', 'radio', 'button', 'submit', 'reset', 'file', 'color'].includes(type);
  }
  return !!t.isContentEditable;
}

/**
 * 149차: 초점 요소가 Space를 스스로 쓰는 누름 칸인지 — 버튼·링크·role=button과 글 칸이 아닌 input(체크 상자·라디오·버튼형 —범위 막대는 Space를 쓰지 않아 뺀다).
 * 창 키(app.ts onKey — 캡처)는 여기서 Space 재생/멈춤을 하지 않는다: 먼저 막으면 정보 탭·깎기 탭 체크 상자가 Space로 켜지고 꺼지지 않고 재생이 대신 켜졌다 멈췄다 했다
 */
export function isPressTarget(t: { tagName?: string; type?: string; getAttribute?(name: string): string | null } | null): boolean {
  const tag = t?.tagName?.toUpperCase();
  if (tag === 'BUTTON' || tag === 'A' || t?.getAttribute?.('role') === 'button') return true;
  return tag === 'INPUT' && t!.type?.toLowerCase() !== 'range' && !isEditableTarget(t);
}

/**
 * 150차: 패널 탭 줄 키(APG Tabs) — 탭 n개 가운데 i번째에서 ←→(끝에서 둘레를 돎)·Home·End로 옮겨 갈 차례. 탭 줄 키가 아니거나 수정 키(Shift·Ctrl·⌘·Alt)가 있으면 -1.
 * panel.ts 탭 줄이 그 탭으로 초점을 옮기고(고르기는 Enter·Space — 수동 활성), 창 키(app.ts onKey — 캡처)는 탭 버튼의 이 키에서 돌아선다
 * (먼저 받으면 재생할 수 있는 문서에서 ←→가 한 이동 걷기로 쓰이고 전파가 막혀 탭 줄에 닿지 않았다)
 */
export function tabMove(e: { key: string; shiftKey: boolean; ctrlKey: boolean; metaKey: boolean; altKey: boolean }, i: number, n: number): number {
  if (e.shiftKey || e.ctrlKey || e.metaKey || e.altKey || i < 0 || i >= n) return -1;
  if (e.key === 'ArrowRight') return (i + 1) % n;
  if (e.key === 'ArrowLeft') return (i + n - 1) % n;
  return e.key === 'Home' ? 0 : e.key === 'End' ? n - 1 : -1;
}
